# ==============================================================================
# Script: 09_Plot_Figs5_6_S3_Spatial_Ensemble.py
# Title: Master Spatial Ensemble Visualization Suite (Figures 5, 6, and S3)
# Description: Loads the 10-fold spatial bootstrap ensemble outputs generated by
#              05_Spatial_Ensemble_MLP_SPAT.py and produces:
#                - Figure 5: Basin-wide area-weighted TTI trajectory (1955-2020)
#                - Figure 6: 6-panel spatio-temporal TTI reconstruction (1970, 1995, 2020)
#                - Figure S3: 6-panel ensemble mean & pixel-wise uncertainty (SD)
# Reference: Stips et al. (2026) - Environmental Modelling & Software
# License: GPL-3.0
# ==============================================================================

import os
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from matplotlib.colors import LinearSegmentedColormap
from tti_common import load_pickle


def get_tti_colormap():
    """Colorblind-safe diverging RdYlBu palette rescaled around GES = 0.71 over [0.4, 1.0]."""
    hex_colors = ["#d73027", "#f46d43", "#fdae61", "#ffffbf", "#abd9e9", "#74add1", "#4575b4"]
    stops = (np.array([0.4, 0.55, 0.68, 0.71, 0.75, 0.85, 1.0]) - 0.4) / (1.0 - 0.4)
    cdict = list(zip(stops, hex_colors))
    cmap = LinearSegmentedColormap.from_list("tti_rdylbu", cdict, N=256)
    cmap.set_bad(color="white")
    return cmap


def df_to_regular_2d_grid(sub_df: pd.DataFrame, val_col: str):
    """Pivot scattered (Longitude, Latitude, val_col) wet pixels onto a regular 2D (lat, lon) array."""
    piv = sub_df.pivot(index="Latitude", columns="Longitude", values=val_col)
    piv = piv.sort_index(ascending=True)  # ascending latitude for pcolormesh/contour
    lons = piv.columns.values.astype(np.float64)
    lats = piv.index.values.astype(np.float64)
    z_grid = piv.values.astype(np.float64)
    return lons, lats, z_grid


def plot_figure_5(ts_df: pd.DataFrame, fig_dir: str):
    years = ts_df["Year"].values
    true_tti = ts_df["True_TTI_Mean"].values
    pred_tti = ts_df["Pred_TTI_Mean"].values
    pred_ci = ts_df["Pred_TTI_CI"].values

    fig, ax = plt.subplots(figsize=(8.5, 5.5))
    ax.axhline(0.71, color="grey", linestyle="--", linewidth=1.3, zorder=1)

    ax.plot(
        years - 0.15, true_tti, color="black", linewidth=2.0, marker="o",
        markersize=7.5, label="Ecosystem Model (True TTI)", zorder=3
    )
    ax.errorbar(
        years + 0.15, pred_tti, yerr=pred_ci, color="#E69F00", linewidth=2.0,
        elinewidth=1.4, capsize=4.5, marker="o", markerfacecolor="white",
        markeredgewidth=1.6, markersize=5.0, label="MLP_SPAT Ensemble (Predicted TTI)", zorder=4
    )

    ax.set_xticks(years)
    ax.set_xticklabels([str(int(y)) for y in years], fontsize=11)
    ax.set_xlabel("Assessment Year (Pentad Center)", fontsize=13, fontweight="bold")
    ax.set_ylabel("Area-Weighted Mean TTI", fontsize=13, fontweight="bold")
    ax.grid(True, color="#d9d9d9", linewidth=0.7, zorder=0)
    ax.spines["top"].set_visible(False)
    ax.spines["right"].set_visible(False)

    fig.suptitle("Temporal Evolution of Mean Trophic Transfer Index", fontsize=15.5, fontweight="bold", y=0.96)
    ax.set_title(
        "Basin-wide reconstruction using a 10-fold spatial bootstrap ensemble",
        fontsize=11.5, color="#4d4d4d", pad=12
    )
    ax.legend(
        loc="upper center", bbox_to_anchor=(0.5, -0.15), ncol=2,
        frameon=False, prop={"weight": "bold", "size": 11}
    )

    out_file = os.path.join(fig_dir, "Figure5_Temporal_TTI_Spatial_Ensemble.png")
    plt.tight_layout(rect=[0, 0.08, 1, 0.93])
    fig.savefig(out_file, dpi=500, facecolor="white")
    plt.close(fig)
    print(f"Figure 5 successfully saved to: {out_file}")


def plot_figure_6(map_df: pd.DataFrame, fig_dir: str):
    target_years = [1970, 1995, 2020]
    cmap = get_tti_colormap()

    fig, axes = plt.subplots(3, 2, figsize=(7.5, 9.5), sharex=True, sharey=True)
    col_titles = ["Ecosystem Model\n(True TTI)", "MLP_SPAT Ensemble\n(Predicted Mean TTI)"]

    for r_i, yr in enumerate(target_years):
        sub_yr = map_df[map_df["Year"] == yr]
        for c_i, val_col in enumerate(["True_TTI", "Ensemble_Mean_TTI"]):
            ax = axes[r_i, c_i]
            ax.set_facecolor("white")
            lons, lats, z_grid = df_to_regular_2d_grid(sub_yr, val_col)
            z_clipped = np.clip(z_grid, 0.4, 1.0)

            im = ax.pcolormesh(
                lons, lats, z_clipped, cmap=cmap, vmin=0.4, vmax=1.0, shading="auto"
            )
            try:
                ax.contour(
                    lons, lats, z_grid, levels=[0.71], colors="black", linewidths=0.75, alpha=0.85
                )
            except Exception:
                pass

            ax.set_xlim(9.0, 30.5)
            ax.set_ylim(53.5, 66.5)
            ax.set_aspect(1.7)
            ax.set_xticks([10, 20, 30])
            ax.set_xticklabels(["10°E", "20°E", "30°E"], fontsize=10.5)
            ax.set_yticks([54, 58, 62, 66])
            ax.set_yticklabels(["54°N", "58°N", "62°N", "66°N"], fontsize=10.5)

            if r_i == 0:
                ax.set_title(col_titles[c_i], fontsize=12, fontweight="bold", pad=8)
            if c_i == 1:
                ax_r = ax.twinx()
                ax_r.set_yticks([])
                ax_r.set_ylabel(
                    f"Pentad Center: {yr}", fontsize=11.5, fontweight="bold", rotation=270, labelpad=15
                )

    fig.supxlabel("Longitude", fontsize=12.5, fontweight="bold", y=0.08)
    fig.supylabel("Latitude", fontsize=12.5, fontweight="bold", x=0.03)
    fig.suptitle(
        "Spatio-Temporal Reconstruction of Baltic Sea Trophic Status",
        fontsize=14.5, fontweight="bold", y=0.97
    )

    cbar_ax = fig.add_axes([0.22, 0.025, 0.56, 0.018])
    cbar = fig.colorbar(im, cax=cbar_ax, orientation="horizontal")
    cbar.set_label("TTI Value:", fontsize=11.5, fontweight="bold", labelpad=4)

    out_file = os.path.join(fig_dir, "Figure6_Spatio_Temporal_TTI_Ensemble_Grid.png")
    plt.tight_layout(rect=[0.04, 0.09, 0.96, 0.94])
    fig.savefig(out_file, dpi=500, facecolor="white")
    plt.close(fig)
    print(f"Figure 6 successfully saved to: {out_file}")


def plot_figure_s3(map_df: pd.DataFrame, fig_dir: str):
    target_years = [1970, 1995, 2020]
    cmap_mean = get_tti_colormap()
    cmap_sd = plt.get_cmap("plasma").copy()
    cmap_sd.set_bad(color="white")

    fig, axes = plt.subplots(3, 2, figsize=(8.5, 9.5), sharex=True, sharey=True)

    for r_i, yr in enumerate(target_years):
        sub_yr = map_df[map_df["Year"] == yr]

        # Left column: Predicted Mean TTI
        ax_m = axes[r_i, 0]
        lons, lats, z_mean = df_to_regular_2d_grid(sub_yr, "Ensemble_Mean_TTI")
        im_m = ax_m.pcolormesh(
            lons, lats, np.clip(z_mean, 0.4, 1.0), cmap=cmap_mean, vmin=0.4, vmax=1.0, shading="auto"
        )
        try:
            ax_m.contour(lons, lats, z_mean, levels=[0.71], colors="black", linewidths=0.75, alpha=0.85)
        except Exception:
            pass
        ax_m.set_xlim(9.0, 30.5)
        ax_m.set_ylim(53.5, 66.5)
        ax_m.set_aspect(1.7)
        ax_m.set_xticks([10, 20, 30])
        ax_m.set_xticklabels(["10°E", "20°E", "30°E"], fontsize=10.5)
        ax_m.set_yticks([54, 58, 62, 66])
        ax_m.set_yticklabels(["54°N", "58°N", "62°N", "66°N"], fontsize=10.5)
        if r_i == 0:
            ax_m.set_title("A: Predicted Mean TTI", fontsize=12.5, fontweight="bold", pad=8)

        # Right column: Ensemble Uncertainty (SD capped at 0.10)
        ax_s = axes[r_i, 1]
        lons, lats, z_sd = df_to_regular_2d_grid(sub_yr, "Ensemble_SD_TTI")
        im_s = ax_s.pcolormesh(
            lons, lats, np.clip(z_sd, 0.0, 0.10), cmap=cmap_sd, vmin=0.0, vmax=0.10, shading="auto"
        )
        ax_s.set_xlim(9.0, 30.5)
        ax_s.set_ylim(53.5, 66.5)
        ax_s.set_aspect(1.7)
        ax_s.set_xticks([10, 20, 30])
        ax_s.set_xticklabels(["10°E", "20°E", "30°E"], fontsize=10.5)
        if r_i == 0:
            ax_s.set_title("B: Spatial Bootstrap Uncertainty", fontsize=12.5, fontweight="bold", pad=8)

        ax_r = ax_s.twinx()
        ax_r.set_yticks([])
        ax_r.set_ylabel(
            f"Pentad Center: {yr}", fontsize=11.5, fontweight="bold", rotation=270, labelpad=15
        )

    fig.supxlabel("Longitude", fontsize=12.5, fontweight="bold", y=0.08)
    fig.supylabel("Latitude", fontsize=12.5, fontweight="bold", x=0.03)
    fig.suptitle(
        "MLP_SPAT Spatial Bootstrap Ensemble (Means and Standard Deviations)",
        fontsize=14.5, fontweight="bold", y=0.97
    )

    cbar_m_ax = fig.add_axes([0.12, 0.025, 0.34, 0.018])
    cbar_m = fig.colorbar(im_m, cax=cbar_m_ax, orientation="horizontal")
    cbar_m.set_label("Mean TTI:", fontsize=11, fontweight="bold")

    cbar_s_ax = fig.add_axes([0.56, 0.025, 0.34, 0.018])
    cbar_s = fig.colorbar(im_s, cax=cbar_s_ax, orientation="horizontal", ticks=[0.0, 0.05, 0.10])
    cbar_s.ax.set_xticklabels(["0.00", "0.05", ">0.10"])
    cbar_s.set_label("TTI SD (Uncertainty):", fontsize=11, fontweight="bold")

    out_file = os.path.join(fig_dir, "Figure_S3_Ensemble_Uncertainty_Maps.png")
    plt.tight_layout(rect=[0.04, 0.09, 0.96, 0.94])
    fig.savefig(out_file, dpi=500, facecolor="white")
    plt.close(fig)
    print(f"Supplementary Figure S3 successfully saved to: {out_file}")


def main():
    in_dir = "./Output" if os.path.exists("./Output") else "./"
    fig_dir = "./Figures"
    os.makedirs(fig_dir, exist_ok=True)

    ts_file = os.path.join(in_dir, "Ensemble_TimeSeries_MLP_SPAT.pkl")
    map_file = os.path.join(in_dir, "Ensemble_Map_Data_MLP_SPAT.pkl")
    if not os.path.exists(ts_file) or not os.path.exists(map_file):
        raise FileNotFoundError("Ensemble output files not found. Run 05_Spatial_Ensemble_MLP_SPAT.py first.")

    ts_df = load_pickle(ts_file)
    map_df = load_pickle(map_file)

    plot_figure_5(ts_df, fig_dir)
    plot_figure_6(map_df, fig_dir)
    plot_figure_s3(map_df, fig_dir)


if __name__ == "__main__":
    main()
